func rootKeys(t *testing.T, doc *crdt.Doc) int {
	t.Helper()
	j, err := doc.GetMap("root").ToJSON()
	if err != nil {
		t.Fatalf("ToJSON: %v", err)
	}
	var m map[string]any
	if err := json.Unmarshal(j, &m); err != nil {
		t.Fatalf("Unmarshal: %v", err)
	}
	return len(m)
}

// TestDocFromV2_NeverReturnsATruncatedDoc pins the invariant the guard exists for:
// docFromV2 either returns the WHOLE document or it returns an error. It must never
// hand back a doc that is quietly smaller than the bytes it was given, because the
// caller persists what it gets and would overwrite the intact original.
//
// Today ygo's ApplyUpdateV2 loses content on the GC fixture (reearth/ygo#231), so
// this takes the error branch. When that is fixed the decode completes and the
// success branch applies. Both are correct; silent truncation is not.
func TestDocFromV2_NeverReturnsATruncatedDoc(t *testing.T) {
	v2, err := hex.DecodeString(fixtureV2WithGC)
	if err != nil {
		t.Fatalf("bad fixture: %v", err)
	}

	doc, err := docFromV2(v2)
	if err != nil {
		if !errors.Is(err, ErrPartialV2Decode) {
			t.Fatalf("want ErrPartialV2Decode, got %v", err)
		}
		return // refused, which is the safe outcome
	}
	if got := rootKeys(t, doc); got != 12 {
		t.Fatalf("docFromV2 returned a truncated document without an error: got %d keys, want 12", got)
	}
}

// TestDocFromV2_AcceptsACompleteDecode is the control: the same document without
// GC structs decodes fully, so the guard is not simply rejecting everything.
func TestDocFromV2_AcceptsACompleteDecode(t *testing.T) {
	v2, err := hex.DecodeString(fixtureV2NoGC)
	if err != nil {
		t.Fatalf("bad fixture: %v", err)
	}

	doc, err := docFromV2(v2)
	if err != nil {
		t.Fatalf("control fixture must decode cleanly, got %v", err)
	}
	if got := rootKeys(t, doc); got != 12 {
		t.Fatalf("control fixture: got %d keys, want 12", got)
	}
}

// TestDocFromV2_GuardCatchesWhatApplyUpdateV2Hides is a regression canary for the
// failure mode the guard exists for: a decode that reports success while dropping
// content.
//
// On ygo >= v1.49.1 this fixture decodes completely, so the test skips. It is kept
// rather than deleted because a future decoder regression would make it run again,
// and it then asserts that the guard actually catches the silent truncation rather
// than letting it through to the flush. A skip here is the healthy state.
func TestDocFromV2_GuardCatchesWhatApplyUpdateV2Hides(t *testing.T) {
	v2, err := hex.DecodeString(fixtureV2WithGC)
	if err != nil {
		t.Fatalf("bad fixture: %v", err)
	}

	raw := crdt.New()
	if err := crdt.ApplyUpdateV2(raw, v2, nil); err != nil {
		t.Skipf("ApplyUpdateV2 now reports an error (%v); the silent-truncation path is gone", err)
	}
	keys := rootKeys(t, raw)
	if keys == 12 {
		t.Skip("ApplyUpdateV2 now decodes this fixture completely; ygo#231 appears fixed")
	}
	t.Logf("ApplyUpdateV2 returned nil but produced %d of 12 keys (%d items left pending)",
		keys, raw.PendingStats().Items)

	if _, err := docFromV2(v2); !errors.Is(err, ErrPartialV2Decode) {
		t.Fatalf("guard failed to catch a silent truncation: %v", err)
	}
}
